    printf("--- Factorial Computation ---\n");
    for (int i = 1; i <= 6; i++) {
        printf("%d! = %lld\n", i, factorial(i));
    }

    printf("\n--- Fibonacci Sequence (First 8 Terms) ---\n");
    for (int i = 0; i < 8; i++) {
        printf("%d ", fibonacci(i));
    }
    printf("\n");

