    FILE *fp_in = fopen(filename, "rb");
    if (fp_in == NULL) {
        printf("Error opening file for read.\n");
        return 1;
    }
    fread(&s_read, sizeof(StudentRecord), 1, fp_in);
    fclose(fp_in);

    printf("Record Recovered from Disk:\n");
    printf("  ID:    %d\n", s_read.id);
    printf("  Name:  %s\n", s_read.name);
