    arr = temp;
    arr[3] = 40;
    arr[4] = 50;

    printf("Resized Heap Block (size %d): ", new_size);
    for (int i = 0; i < new_size; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");

